#!/bin/bash
# Usage: 03_stacta_verify.sh <proto_root> <cog_dir>
P=$1; COG=$2; S=$P/stacta/depths_processed.stacta.json; cd /tmp
ext() { gdalinfo "$1" | python3 -c "import sys,re; t=sys.stdin.read(); ul=re.search(r'Upper Left\s*\(\s*([-\d.]+),\s*([-\d.]+)',t); lr=re.search(r'Lower Right\s*\(\s*([-\d.]+),\s*([-\d.]+)',t); print(ul[1],lr[2],lr[1],ul[2])"; }
echo "-- open: $(gdalinfo --version | cut -d, -f1)"; ( time (gdalinfo $S >/dev/null) ) 2>&1 | grep real; gdalinfo $S 2>&1 | grep -E 'Size is|Overviews|ERROR' | head -3
echo "-- (a) level-10 window vs COG tile"; E=$(ext $COG/10_17252_13419.tif); gdal_translate -q -projwin_srs EPSG:4326 -projwin $(echo $E | awk '{print $1,$4,$3,$2}') $S sa.tif 2>&1 | grep -v -i warning; gdalinfo -checksum sa.tif | grep Checksum | tr '\n' ' '; echo " (tile: 20175 15241)"
echo "-- (b) level-9 and level-3 windows vs overview tiles"; for T in $COG/overviews/9_8626_6709.tif $(ls $COG/overviews/3_*.tif | head -1); do l=$(basename $T | cut -d_ -f1); s=$(python3 -c "print(8/2**$l/960)"); E=$(ext $T); gdal_translate -q -projwin_srs EPSG:4326 -projwin $(echo $E | awk '{print $1,$4,$3,$2}') -tr $s $s $S so.tif 2>&1 | grep -v -i warning; printf '   L%s stacta: ' $l; gdalinfo -checksum so.tif | grep Checksum | tr '\n' ' '; printf '  tile: '; gdalinfo -checksum $T | grep Checksum | tr '\n' ' '; echo; done
echo "-- (c) POLAR 75N (x3) and 85N (x9) through STACTA"; for t in 10_21888_4693 10_23168_1564; do E=$(ext $P/depths/polar_synth/$t.tif); gdal_translate -q -projwin_srs EPSG:4326 -projwin $(echo $E | awk '{print $1,$4,$3,$2}') $S sp.tif 2>&1 | grep -v -i warning | head -2; printf '   %s: ' $t; gdalinfo -stats sp.tif 2>/dev/null | grep -E 'Size is|STATISTICS_(MINIMUM|MAXIMUM|VALID_PERCENT)' | head -4 | tr '\n' ' ' | sed 's/  */ /g'; echo; done
